CREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA extensions;

CREATE TABLE IF NOT EXISTS public.gcc_supported_currencies (
 currency_code text PRIMARY KEY, currency_name text NOT NULL, iso_numeric_code text NOT NULL CHECK (iso_numeric_code ~ '^[0-9]{3}$'), minor_unit smallint NOT NULL CHECK (minor_unit BETWEEN 0 AND 6), gcc_member boolean NOT NULL DEFAULT false, enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS public.gcc_tax_business_access (
 business_id uuid NOT NULL, tax_year integer NOT NULL CHECK (tax_year BETWEEN 2020 AND 2100), country_code text NOT NULL CHECK (country_code IN ('AE','SA','BH','KW','OM','QA')), vat_registered boolean NOT NULL DEFAULT false, corporate_tax_registered boolean NOT NULL DEFAULT false, corporate_tax_baseline_minor bigint NOT NULL DEFAULT 37500000 CHECK (corporate_tax_baseline_minor >= 0), reporting_currency text NOT NULL DEFAULT 'AED' REFERENCES public.gcc_supported_currencies(currency_code), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (business_id,tax_year)
);
CREATE TABLE IF NOT EXISTS public.gcc_invoice_sequences (
 business_id uuid NOT NULL, country_code text NOT NULL CHECK (country_code IN ('AE','SA','BH','KW','OM','QA')), tax_year integer NOT NULL CHECK (tax_year BETWEEN 2020 AND 2100), next_number bigint NOT NULL DEFAULT 1 CHECK (next_number >= 1), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (business_id,country_code,tax_year)
);
CREATE TABLE IF NOT EXISTS public.exchange_rates (
 rate_id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(), base_currency text NOT NULL REFERENCES public.gcc_supported_currencies(currency_code), quote_currency text NOT NULL REFERENCES public.gcc_supported_currencies(currency_code), rate_date date NOT NULL, rate numeric(28,12) NOT NULL CHECK (rate > 0), source text NOT NULL CHECK (length(btrim(source)) > 0), source_reference text, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, UNIQUE(base_currency,quote_currency,rate_date,source)
);
CREATE TABLE IF NOT EXISTS public.gcc_data_residency_lineage (
 lineage_id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(), business_id uuid NOT NULL, country_code text NOT NULL CHECK (country_code IN ('AE','SA','BH','KW','OM','QA')), jurisdiction text NOT NULL CHECK (length(btrim(jurisdiction)) > 0), residency_class text NOT NULL CHECK (length(btrim(residency_class)) > 0), effective_from timestamptz NOT NULL, effective_to timestamptz, evidence_hash text NOT NULL CHECK (evidence_hash ~ '^[0-9a-fA-F]{64}$'), previous_hash text CHECK (previous_hash IS NULL OR previous_hash ~ '^[0-9a-fA-F]{64}$'), lineage_hash text NOT NULL CHECK (lineage_hash ~ '^[0-9a-fA-F]{64}$'), created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, CHECK(effective_to IS NULL OR effective_to > effective_from)
);
CREATE TABLE IF NOT EXISTS public.fta_audit_log (
 audit_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, business_id uuid NOT NULL, event_type text NOT NULL CHECK(length(btrim(event_type))>0), entity_type text NOT NULL CHECK(length(btrim(entity_type))>0), entity_id uuid, invoice_number bigint, event_payload jsonb NOT NULL DEFAULT '{}'::jsonb, previous_hash text CHECK(previous_hash IS NULL OR previous_hash ~ '^[0-9a-fA-F]{64}$'), event_hash text NOT NULL CHECK(event_hash ~ '^[0-9a-fA-F]{64}$'), created_at timestamptz NOT NULL DEFAULT now(), created_by uuid
);
CREATE TABLE IF NOT EXISTS public.gcc_tax_ledger (
 tax_entry_id uuid PRIMARY KEY DEFAULT extensions.gen_random_uuid(), business_id uuid NOT NULL, tax_year integer NOT NULL CHECK(tax_year BETWEEN 2020 AND 2100), country_code text NOT NULL CHECK(country_code IN ('AE','SA','BH','KW','OM','QA')), tax_type text NOT NULL CHECK(tax_type IN('VAT','CORPORATE_TAX')), invoice_number bigint, transaction_date date NOT NULL, currency_code text NOT NULL REFERENCES public.gcc_supported_currencies(currency_code), taxable_amount numeric(18,4) NOT NULL CHECK(taxable_amount>=0), tax_rate_bps integer NOT NULL CHECK(tax_rate_bps BETWEEN 0 AND 10000), tax_amount numeric(18,4) NOT NULL CHECK(tax_amount>=0), amount_aed numeric(18,4) NOT NULL CHECK(amount_aed>=0), exchange_rate numeric(28,12) NOT NULL CHECK(exchange_rate>0), tax_status text NOT NULL CHECK(tax_status IN('TAXABLE','ZERO_RATED','EXEMPT','OUT_OF_SCOPE')), source_entity_type text NOT NULL CHECK(length(btrim(source_entity_type))>0), source_entity_id uuid, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid
);
INSERT INTO public.gcc_supported_currencies(currency_code,currency_name,iso_numeric_code,minor_unit,gcc_member) VALUES ('AED','United Arab Emirates Dirham','784',2,true),('SAR','Saudi Riyal','682',2,true),('BHD','Bahraini Dinar','048',3,true),('KWD','Kuwaiti Dinar','414',3,true),('OMR','Omani Rial','512',3,true),('QAR','Qatari Riyal','634',2,true),('USD','United States Dollar','840',2,false) ON CONFLICT(currency_code) DO UPDATE SET currency_name=excluded.currency_name,iso_numeric_code=excluded.iso_numeric_code,minor_unit=excluded.minor_unit,gcc_member=excluded.gcc_member;
CREATE OR REPLACE FUNCTION public.gcc_calculate_tax(p_taxable_amount numeric,p_tax_rate_bps integer) RETURNS numeric LANGUAGE sql IMMUTABLE STRICT SET search_path=pg_catalog,public,extensions,pg_temp AS $$ SELECT round((p_taxable_amount*p_tax_rate_bps::numeric)/10000::numeric,4) $$;
CREATE OR REPLACE FUNCTION public.fta_next_invoice_number(p_business_id uuid,p_country_code text,p_tax_year integer) RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,extensions,pg_temp AS $$ DECLARE v_number bigint; BEGIN IF p_business_id IS NULL OR p_country_code NOT IN('AE','SA','BH','KW','OM','QA') OR p_tax_year NOT BETWEEN 2020 AND 2100 THEN RAISE EXCEPTION 'invalid invoice sequence request'; END IF; INSERT INTO public.gcc_invoice_sequences(business_id,country_code,tax_year,next_number) VALUES(p_business_id,p_country_code,p_tax_year,2) ON CONFLICT(business_id,country_code,tax_year) DO UPDATE SET next_number=public.gcc_invoice_sequences.next_number+1,updated_at=now() RETURNING next_number-1 INTO v_number; RETURN v_number; END $$;
CREATE OR REPLACE FUNCTION public.gcc_post_tax_transaction(p_business_id uuid,p_tax_year integer,p_country_code text,p_tax_type text,p_invoice_number bigint,p_transaction_date date,p_currency_code text,p_taxable_amount numeric,p_tax_rate_bps integer,p_exchange_rate numeric,p_tax_status text,p_source_entity_type text,p_source_entity_id uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,extensions,pg_temp AS $$ DECLARE v_id uuid; v_tax numeric; v_aed numeric; BEGIN IF p_business_id IS NULL OR p_tax_year NOT BETWEEN 2020 AND 2100 OR p_country_code NOT IN('AE','SA','BH','KW','OM','QA') OR p_tax_type NOT IN('VAT','CORPORATE_TAX') OR p_currency_code IS NULL OR p_taxable_amount<0 OR p_tax_rate_bps NOT BETWEEN 0 AND 10000 OR p_exchange_rate<=0 OR p_tax_status NOT IN('TAXABLE','ZERO_RATED','EXEMPT','OUT_OF_SCOPE') OR length(btrim(p_source_entity_type))=0 THEN RAISE EXCEPTION 'invalid fiscal transaction'; END IF; v_tax:=public.gcc_calculate_tax(p_taxable_amount,p_tax_rate_bps); v_aed:=round((p_taxable_amount+v_tax)*p_exchange_rate,4); INSERT INTO public.gcc_tax_ledger(business_id,tax_year,country_code,tax_type,invoice_number,transaction_date,currency_code,taxable_amount,tax_rate_bps,tax_amount,amount_aed,exchange_rate,tax_status,source_entity_type,source_entity_id,created_by) VALUES(p_business_id,p_tax_year,p_country_code,p_tax_type,p_invoice_number,p_transaction_date,p_currency_code,p_taxable_amount,p_tax_rate_bps,v_tax,v_aed,p_exchange_rate,p_tax_status,p_source_entity_type,p_source_entity_id,auth.uid()) RETURNING tax_entry_id INTO v_id; RETURN v_id; END $$;
CREATE OR REPLACE FUNCTION public.fta_append_audit_event(p_business_id uuid,p_event_type text,p_entity_type text,p_entity_id uuid,p_invoice_number bigint,p_event_payload jsonb) RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,extensions,pg_temp AS $$ DECLARE v_id bigint; v_prev text; v_hash text; BEGIN IF p_business_id IS NULL OR length(btrim(p_event_type))=0 OR length(btrim(p_entity_type))=0 THEN RAISE EXCEPTION 'invalid audit event'; END IF; SELECT event_hash INTO v_prev FROM public.fta_audit_log WHERE business_id=p_business_id ORDER BY audit_id DESC LIMIT 1 FOR UPDATE; v_hash:=encode(extensions.digest(convert_to(p_business_id::text||':'||p_event_type||':'||p_entity_type||':'||coalesce(p_entity_id::text,'')||':'||coalesce(p_invoice_number::text,'')||':'||coalesce(p_event_payload::text,'')||':'||coalesce(v_prev,''),'UTF8'),'sha256'),'hex'); INSERT INTO public.fta_audit_log(business_id,event_type,entity_type,entity_id,invoice_number,event_payload,previous_hash,event_hash,created_by) VALUES(p_business_id,p_event_type,p_entity_type,p_entity_id,p_invoice_number,coalesce(p_event_payload,'{}'::jsonb),v_prev,v_hash,auth.uid()) RETURNING audit_id INTO v_id; RETURN v_id; END $$;
CREATE OR REPLACE FUNCTION public.gcc_residency_append(p_business_id uuid,p_country_code text,p_jurisdiction text,p_residency_class text,p_effective_from timestamptz,p_effective_to timestamptz,p_evidence_hash text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,extensions,pg_temp AS $$ DECLARE v_id uuid; v_prev text; v_hash text; BEGIN IF p_business_id IS NULL OR p_country_code NOT IN('AE','SA','BH','KW','OM','QA') OR length(btrim(p_jurisdiction))=0 OR length(btrim(p_residency_class))=0 OR p_evidence_hash !~ '^[0-9a-fA-F]{64}$' OR(p_effective_to IS NOT NULL AND p_effective_to<=p_effective_from) THEN RAISE EXCEPTION 'invalid residency lineage'; END IF; SELECT lineage_hash INTO v_prev FROM public.gcc_data_residency_lineage WHERE business_id=p_business_id ORDER BY created_at DESC,lineage_id DESC LIMIT 1 FOR UPDATE; v_hash:=encode(extensions.digest(convert_to(p_business_id::text||':'||p_country_code||':'||p_jurisdiction||':'||p_residency_class||':'||p_effective_from::text||':'||coalesce(p_effective_to::text,'')||':'||p_evidence_hash||':'||coalesce(v_prev,''),'UTF8'),'sha256'),'hex'); INSERT INTO public.gcc_data_residency_lineage(business_id,country_code,jurisdiction,residency_class,effective_from,effective_to,evidence_hash,previous_hash,lineage_hash,created_by) VALUES(p_business_id,p_country_code,p_jurisdiction,p_residency_class,p_effective_from,p_effective_to,p_evidence_hash,v_prev,v_hash,auth.uid()) RETURNING lineage_id INTO v_id; RETURN v_id; END $$;
CREATE OR REPLACE FUNCTION public.gcc_get_regional_tax_summary(p_business_id uuid,p_tax_year integer) RETURNS TABLE(country_code text,tax_type text,taxable_amount numeric,tax_amount numeric,amount_aed numeric,entry_count bigint) LANGUAGE sql SECURITY INVOKER STABLE SET search_path=pg_catalog,public,extensions,pg_temp AS $$ SELECT l.country_code,l.tax_type,sum(l.taxable_amount),sum(l.tax_amount),sum(l.amount_aed),count(*) FROM public.gcc_tax_ledger l WHERE l.business_id=p_business_id AND l.tax_year=p_tax_year AND EXISTS(SELECT 1 FROM public.business_members m WHERE m.business_id=l.business_id AND m.user_id=(SELECT auth.uid())) GROUP BY l.country_code,l.tax_type ORDER BY l.country_code,l.tax_type $$;
CREATE OR REPLACE FUNCTION public.gcc_tax_ledger_immutable_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public,extensions,pg_temp AS $$ BEGIN RAISE EXCEPTION 'gcc_tax_ledger is append-only'; END $$;
CREATE OR REPLACE FUNCTION public.fta_audit_immutable_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public,extensions,pg_temp AS $$ BEGIN RAISE EXCEPTION 'fta_audit_log is append-only'; END $$;
CREATE OR REPLACE FUNCTION public.exchange_rates_immutable_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public,extensions,pg_temp AS $$ BEGIN RAISE EXCEPTION 'exchange_rates is append-only'; END $$;
CREATE OR REPLACE FUNCTION public.gcc_residency_immutable_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public,extensions,pg_temp AS $$ BEGIN RAISE EXCEPTION 'gcc_data_residency_lineage is append-only'; END $$;
CREATE INDEX IF NOT EXISTS gcc_tax_business_access_country_idx ON public.gcc_tax_business_access(country_code,tax_year);
CREATE INDEX IF NOT EXISTS exchange_rates_pair_date_idx ON public.exchange_rates(base_currency,quote_currency,rate_date DESC);
CREATE INDEX IF NOT EXISTS gcc_residency_business_effective_idx ON public.gcc_data_residency_lineage(business_id,effective_from DESC);
CREATE INDEX IF NOT EXISTS fta_audit_business_created_idx ON public.fta_audit_log(business_id,created_at DESC,audit_id DESC);
CREATE INDEX IF NOT EXISTS gcc_tax_ledger_business_date_idx ON public.gcc_tax_ledger(business_id,transaction_date DESC,tax_entry_id);
CREATE INDEX IF NOT EXISTS gcc_tax_ledger_source_idx ON public.gcc_tax_ledger(source_entity_type,source_entity_id);
ALTER TABLE public.gcc_supported_currencies ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.gcc_tax_business_access ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.gcc_invoice_sequences ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.exchange_rates ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.gcc_data_residency_lineage ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.fta_audit_log ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.gcc_tax_ledger ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.gcc_supported_currencies,public.gcc_tax_business_access,public.gcc_invoice_sequences,public.exchange_rates,public.gcc_data_residency_lineage,public.fta_audit_log,public.gcc_tax_ledger FROM anon,authenticated;
GRANT SELECT ON public.gcc_supported_currencies TO authenticated;
GRANT SELECT ON public.gcc_tax_business_access,public.exchange_rates,public.gcc_data_residency_lineage,public.fta_audit_log,public.gcc_tax_ledger TO authenticated;
REVOKE ALL ON FUNCTION public.gcc_calculate_tax(numeric,integer) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.gcc_calculate_tax(numeric,integer) TO authenticated;
REVOKE ALL ON FUNCTION public.fta_next_invoice_number(uuid,text,integer) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.fta_next_invoice_number(uuid,text,integer) TO service_role;
REVOKE ALL ON FUNCTION public.gcc_post_tax_transaction(uuid,integer,text,text,bigint,date,text,numeric,integer,numeric,text,text,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.gcc_post_tax_transaction(uuid,integer,text,text,bigint,date,text,numeric,integer,numeric,text,text,uuid) TO service_role;
REVOKE ALL ON FUNCTION public.fta_append_audit_event(uuid,text,text,uuid,bigint,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.fta_append_audit_event(uuid,text,text,uuid,bigint,jsonb) TO service_role;
REVOKE ALL ON FUNCTION public.gcc_residency_append(uuid,text,text,text,timestamptz,timestamptz,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.gcc_residency_append(uuid,text,text,text,timestamptz,timestamptz,text) TO service_role;
REVOKE ALL ON FUNCTION public.gcc_get_regional_tax_summary(uuid,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.gcc_get_regional_tax_summary(uuid,integer) TO authenticated;
DROP POLICY IF EXISTS gcc_supported_currencies_authenticated_select ON public.gcc_supported_currencies;
CREATE POLICY gcc_supported_currencies_authenticated_select ON public.gcc_supported_currencies FOR SELECT TO authenticated USING(true);
DROP POLICY IF EXISTS gcc_tax_business_access_authenticated_select ON public.gcc_tax_business_access;
CREATE POLICY gcc_tax_business_access_authenticated_select ON public.gcc_tax_business_access FOR SELECT TO authenticated USING(business_id IN(SELECT m.business_id FROM public.business_members m WHERE m.user_id=(SELECT auth.uid())));
DROP POLICY IF EXISTS exchange_rates_authenticated_select ON public.exchange_rates;
CREATE POLICY exchange_rates_authenticated_select ON public.exchange_rates FOR SELECT TO authenticated USING(true);
DROP POLICY IF EXISTS gcc_residency_authenticated_select ON public.gcc_data_residency_lineage;
CREATE POLICY gcc_residency_authenticated_select ON public.gcc_data_residency_lineage FOR SELECT TO authenticated USING(business_id IN(SELECT m.business_id FROM public.business_members m WHERE m.user_id=(SELECT auth.uid())));
DROP POLICY IF EXISTS fta_audit_authenticated_select ON public.fta_audit_log;
CREATE POLICY fta_audit_authenticated_select ON public.fta_audit_log FOR SELECT TO authenticated USING(business_id IN(SELECT m.business_id FROM public.business_members m WHERE m.user_id=(SELECT auth.uid())));
DROP POLICY IF EXISTS gcc_tax_ledger_authenticated_select ON public.gcc_tax_ledger;
CREATE POLICY gcc_tax_ledger_authenticated_select ON public.gcc_tax_ledger FOR SELECT TO authenticated USING(business_id IN(SELECT m.business_id FROM public.business_members m WHERE m.user_id=(SELECT auth.uid())));
DROP TRIGGER IF EXISTS gcc_tax_ledger_immutable ON public.gcc_tax_ledger;
CREATE TRIGGER gcc_tax_ledger_immutable BEFORE UPDATE OR DELETE ON public.gcc_tax_ledger FOR EACH ROW EXECUTE FUNCTION public.gcc_tax_ledger_immutable_guard();
DROP TRIGGER IF EXISTS fta_audit_immutable ON public.fta_audit_log;
CREATE TRIGGER fta_audit_immutable BEFORE UPDATE OR DELETE ON public.fta_audit_log FOR EACH ROW EXECUTE FUNCTION public.fta_audit_immutable_guard();
DROP TRIGGER IF EXISTS exchange_rates_immutable ON public.exchange_rates;
CREATE TRIGGER exchange_rates_immutable BEFORE UPDATE OR DELETE ON public.exchange_rates FOR EACH ROW EXECUTE FUNCTION public.exchange_rates_immutable_guard();
DROP TRIGGER IF EXISTS gcc_residency_immutable ON public.gcc_data_residency_lineage;
CREATE TRIGGER gcc_residency_immutable BEFORE UPDATE OR DELETE ON public.gcc_data_residency_lineage FOR EACH ROW EXECUTE FUNCTION public.gcc_residency_immutable_guard();
GRANT USAGE,SELECT ON SEQUENCE public.fta_audit_log_audit_id_seq TO service_role;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.gcc_invoice_sequences TO service_role;
GRANT SELECT,INSERT ON public.exchange_rates TO service_role;
GRANT SELECT,INSERT ON public.gcc_tax_ledger,public.fta_audit_log,public.gcc_data_residency_lineage TO service_role;